constraint.expression:

import re
UUID = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')

def check(topics):
    """topics: list of dicts with 'guid' and 'server_id'. Returns violations."""
    bad = [t['guid'] for t in topics if not UUID.match(t['guid'])]
    for key in ('guid', 'server_id'):
        seen = set()
        for t in topics:
            if t[key] in seen:
                bad.append(t[key])
            seen.add(t[key])
    return bad  # non-empty = violation


ALLOWED = {
    'Open': {'Assigned', 'Rejected'},
    'Assigned': {'In progress', 'Resolved'},
    'In progress': {'Resolved'},
    'Resolved': {'Closed', 'Reopened'},
    'Reopened': {'Assigned'},
}

def check(status_history):
    """status_history: statuses of one topic in time order."""
    return [(a, b) for a, b in zip(status_history, status_history[1:])
            if b not in ALLOWED.get(a, set())]  # non-empty = violation


@prefix sh:  <http://www.w3.org/ns/shacl#> .
@prefix bcf: <https://example.org/bcf#> .

bcf:SafetyCriticalDefectShape a sh:NodeShape ;
  sh:targetClass bcf:Topic ;
  sh:or (
    [ sh:path bcf:label ; sh:not [ sh:hasValue "Safety" ] ]
    [ sh:path bcf:priority ; sh:hasValue "P1 - Critical" ]
  ) ;
  sh:message "BR-DM-08: a safety-critical defect shall have priority P1 - Critical" .


from datetime import timedelta
LIMIT = {'P1 - Critical': 1, 'P2 - High': 7, 'P3 - Medium': 14, 'P4 - Low': 30}

def check(priority, triaged_on, due_date):
    return due_date - triaged_on > timedelta(days=LIMIT[priority])  # True = violation
